insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Nos casos em que somente se procede mediante queixa, considera-se perempta a ação penal quando, iniciada esta, o querelante deixar de promover o andamento do processo durante 30 dias seguidos; quando, falecendo o querelante ou sobrevindo sua incapacidade, não comparecer em juízo, para prosseguir no processo, dentro de 60 dias, qualquer das pessoas a quem couber fazê-lo, ressalvado o art. 36; quando o querelante deixar de comparecer, sem motivo justificado, a qualquer ato do processo a que deva estar presente, ou deixar de formular o pedido de condenação nas alegações finais; ou quando, sendo o querelante pessoa jurídica, esta se extinguir sem deixar sucessor.', '["I: inércia por 30 dias seguidos.","II: morte ou incapacidade do querelante sem sucessor em 60 dias.","III: ausência injustificada a ato ou falta de pedido de condenação nas alegações finais.","IV: pessoa jurídica extinta sem sucessor."]'::jsonb, '["Perempção só ocorre na ação privada.","Prazo de 30 dias seguidos; 60 dias para sucessão."]'::jsonb, 'Querelante deixa de pedir a condenação nas alegações finais: perempção.', '["Assertiva que aplica a perempção à ação penal pública erra."]'::jsonb, '[{"termo":"Perempção","significado":"Perda do direito de prosseguir na ação privada por negligência do querelante."}]'::jsonb, '["Art. 36","Art. 107, IV do Código Penal"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-60'
