insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Não impedirão igualmente a propositura da ação civil o despacho de arquivamento do inquérito ou das peças de informação; a decisão que julgar extinta a punibilidade; e a sentença absolutória que decidir que o fato imputado não constitui crime.', '["Arquivamento do inquérito não impede a ação civil.","Extinção da punibilidade não impede a ação civil.","Sentença absolutória por fato atípico não impede a ação civil."]'::jsonb, '["Independência relativa entre as esferas."]'::jsonb, 'Inquérito arquivado: a vítima ainda pode pedir indenização no cível.', '["Assertiva que impede a ação civil após o arquivamento do inquérito erra."]'::jsonb, '[]'::jsonb, '["Art. 66"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-67'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Quando o titular do direito à reparação do dano for pobre, a execução da sentença condenatória ou a ação civil será promovida, a seu requerimento, pelo Ministério Público.', '["Titular pobre do direito à reparação.","MP promove, a requerimento, a execução da sentença penal (art. 63) ou a ação civil (art. 64)."]'::jsonb, '["O STF reconheceu a inconstitucionalidade progressiva: onde houver Defensoria Pública, a legitimidade é dela."]'::jsonb, 'Vítima pobre, em comarca sem Defensoria, pede ao MP que execute a sentença condenatória.', '["Assertiva que atribui ao Ministério Público a execução cível do dano para qualquer vítima, mesmo não pobre, erra."]'::jsonb, '[]'::jsonb, '["Art. 32","Art. 63","Art. 64"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-68'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Determinam a competência jurisdicional: o lugar da infração; o domicílio ou a residência do réu; a natureza da infração; a distribuição; a conexão ou continência; a prevenção; e a prerrogativa de função.', '["Lugar da infração.","Domicílio ou residência do réu.","Natureza da infração.","Distribuição.","Conexão ou continência.","Prevenção.","Prerrogativa de função."]'::jsonb, '["Rol de critérios de competência; cada um é detalhado nos artigos seguintes."]'::jsonb, 'O crime ocorrido na comarca A é, em regra, julgado ali, pelo critério do lugar da infração.', '["Assertiva que exclui a prevenção do rol de critérios de competência erra."]'::jsonb, '[]'::jsonb, '["Art. 70","Art. 84"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-69'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A competência será, de regra, determinada pelo lugar em que se consumar a infração (teoria do resultado) ou, no caso de tentativa, pelo lugar do último ato de execução. Se a execução começou no território nacional e a infração se consumou fora dele, a competência é do lugar do último ato de execução no Brasil. Se o último ato de execução foi praticado fora do território nacional, é competente o juiz do lugar em que o crime, embora parcialmente, tenha produzido ou devia produzir seu resultado. Quando incerto o limite territorial entre jurisdições, ou quando a infração for praticada nas divisas, a competência firma-se pela prevenção. Nos crimes de estelionato praticados mediante depósito, cheque sem fundos ou com pagamento frustrado, ou transferência de valores, a competência é definida pelo domicílio da vítima; havendo várias vítimas, firma-se pela prevenção.', '["Regra: lugar da consumação.","Tentativa: lugar do último ato de execução.","§1º e §2º: crimes que cruzam a fronteira.","§3º: limites incertos ou divisas: prevenção.","§4º: estelionato por depósito, cheque, transferência: domicílio da vítima; várias vítimas: prevenção."]'::jsonb, '["O §4º (Lei nº 14.155, de 2021) fixa o domicílio da VÍTIMA para certas fraudes.","Regra geral: teoria do resultado."]'::jsonb, 'Estelionato por transferência de valores é julgado no domicílio da vítima.', '["Assertiva que fixa o domicílio do réu como regra geral de competência erra: a regra é o lugar da consumação."]'::jsonb, '[]'::jsonb, '["Art. 69","Art. 71","Art. 72"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-70'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Tratando-se de infração continuada ou permanente, praticada em território de duas ou mais jurisdições, a competência firmar-se-á pela prevenção.', '["Crime continuado ou permanente em mais de uma jurisdição: prevenção."]'::jsonb, '["Prevenção: o juiz que primeiro conhece do caso."]'::jsonb, 'Sequestro que se prolonga por dois municípios: competente o juízo prevento.', '["Assertiva que fixa o domicílio do réu para crimes permanentes em várias jurisdições erra: aplica-se a prevenção."]'::jsonb, '[]'::jsonb, '["Art. 83"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-71'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Não sendo conhecido o lugar da infração, a competência regula-se pelo domicílio ou residência do réu. Se o réu tiver mais de uma residência, firma-se pela prevenção. Se não tiver residência certa ou for ignorado seu paradeiro, é competente o juiz que primeiro tomar conhecimento do fato.', '["Lugar da infração desconhecido: domicílio ou residência do réu.","Mais de uma residência: prevenção.","Sem residência certa ou paradeiro ignorado: o juiz que primeiro conhecer do fato."]'::jsonb, '["Critério subsidiário ao lugar da infração."]'::jsonb, 'Não se sabe onde o crime ocorreu: vale o domicílio do réu.', '["Assertiva que aplica o domicílio do réu mesmo quando conhecido o lugar da infração, no art. 72, erra."]'::jsonb, '[]'::jsonb, '["Art. 70","Art. 83"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-72'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Nos casos de exclusiva ação privada, o querelante poderá preferir o foro de domicílio ou da residência do réu, ainda quando conhecido o lugar da infração.', '["Ação exclusivamente privada: o querelante pode escolher o foro do domicílio do réu."]'::jsonb, '["Faculdade do querelante, apenas na ação EXCLUSIVAMENTE privada."]'::jsonb, 'Em calúnia, o querelante ajuíza a queixa no domicílio do querelado.', '["Assertiva que estende a escolha do foro à ação pública erra."]'::jsonb, '[]'::jsonb, '["Art. 70"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-73'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A competência pela natureza da infração é regulada pelas leis de organização judiciária, salvo a competência privativa do Tribunal do Júri. Compete ao Tribunal do Júri julgar os crimes dolosos contra a vida: homicídio doloso (simples e qualificado), induzimento, instigação ou auxílio a suicídio, infanticídio e aborto, consumados ou tentados. Se, iniciado o processo perante um juiz, houver desclassificação para infração da competência de outro, o processo é remetido a este, salvo se mais graduada for a jurisdição do primeiro, que terá sua competência prorrogada. Se o juiz da pronúncia desclassificar para infração de competência de juiz singular, aplica-se o art. 410; se a desclassificação for do próprio Júri, o presidente profere a sentença.', '["Natureza da infração: leis de organização judiciária, ressalvado o Júri.","§1º: Júri julga crimes dolosos contra a vida, consumados ou tentados.","§2º: desclassificação leva o processo ao juízo competente, salvo jurisdição mais graduada.","§3º: desclassificação na pronúncia (art. 410) ou pelo Júri (presidente sentencia)."]'::jsonb, '["O homicídio culposo NÃO é do Júri.","Desclassificação feita pelo Júri: o presidente sentencia (art. 492, §2º)."]'::jsonb, 'Homicídio doloso tentado é julgado pelo Tribunal do Júri.', '["Assertiva que atribui ao Júri o homicídio culposo erra: o Júri julga crimes dolosos contra a vida."]'::jsonb, '[]'::jsonb, '["Art. 410","Art. 492"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-74'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A precedência da distribuição fixa a competência quando, na mesma circunscrição judiciária, houver mais de um juiz igualmente competente. A distribuição realizada para a concessão de fiança, a decretação de prisão preventiva ou qualquer diligência anterior à denúncia ou queixa previne a da ação penal.', '["Mais de um juiz igualmente competente: vale a precedência da distribuição.","Distribuição de fiança, preventiva ou diligência prévia previne a ação penal."]'::jsonb, '["Há conexão com a prevenção do art. 83."]'::jsonb, 'A distribuição do pedido de prisão preventiva torna aquele juiz prevento para a futura ação penal.', '["Assertiva que nega efeito preventivo à distribuição de diligência anterior à denúncia erra."]'::jsonb, '[]'::jsonb, '["Art. 83"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-75'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A competência será determinada pela conexão: se, ocorrendo duas ou mais infrações, houverem sido praticadas ao mesmo tempo por várias pessoas reunidas, ou por várias pessoas em concurso, embora diverso o tempo e o lugar, ou por várias pessoas umas contra as outras (conexão intersubjetiva); se umas houverem sido praticadas para facilitar ou ocultar as outras, ou para conseguir impunidade ou vantagem (conexão consequencial ou teleológica); ou quando a prova de uma infração ou de suas circunstâncias elementares influir na prova de outra (conexão probatória).', '["I: conexão intersubjetiva (por simultaneidade, por concurso ou por reciprocidade).","II: conexão teleológica ou consequencial.","III: conexão probatória (instrumental)."]'::jsonb, '["Três espécies de conexão."]'::jsonb, 'Crime praticado para ocultar outro: conexão consequencial.', '["Assertiva que limita a conexão à hipótese de várias pessoas reunidas erra."]'::jsonb, '[{"termo":"Conexão","significado":"Vínculo entre infrações que justifica o julgamento conjunto."}]'::jsonb, '["Art. 77","Art. 78","Art. 79"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-76'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A competência é determinada pela continência quando duas ou mais pessoas forem acusadas pela mesma infração (cumulação subjetiva), ou no caso de infração cometida nas condições previstas nos arts. 51, § 1º, 53, segunda parte, e 54 do Código Penal (concurso formal, erro na execução e resultado diverso do pretendido).', '["I: várias pessoas acusadas pela mesma infração.","II: concurso formal, aberratio ictus e aberratio criminis com resultado duplo."]'::jsonb, '["Continência: um fato com várias pessoas ou várias consequências de uma só conduta."]'::jsonb, 'Dois acusados do mesmo roubo: continência por cumulação subjetiva.', '["Assertiva que identifica a continência com a conexão probatória erra."]'::jsonb, '[{"termo":"Continência","significado":"Uma causa está contida em outra; o julgamento é conjunto."}]'::jsonb, '["Art. 76","Art. 79"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-77'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Na determinação da competência por conexão ou continência, observam-se as seguintes regras: no concurso entre a competência do júri e a de outro órgão da jurisdição comum, prevalece o júri, salvo os casos de homicídios cometidos por membros de organizações criminosas ultraviolentas, grupo paramilitar ou milícia privada, ou sua tentativa; no concurso de jurisdições da mesma categoria, preponderará a do lugar da infração à qual for cominada a pena mais grave, prevalecerá a do lugar com maior número de infrações se as penas forem de igual gravidade, e firmar-se-á a prevenção nos demais casos; no concurso de jurisdições de diversas categorias, predomina a de maior graduação; e no concurso entre a jurisdição comum e a especial, prevalece esta.', '["I: júri prevalece sobre outros órgãos da jurisdição comum (com exceção para organizações ultraviolentas, grupo paramilitar ou milícia).","II, a: pena mais grave.","II, b: maior número de infrações, se penas iguais.","II, c: prevenção nos demais casos.","III: maior graduação.","IV: jurisdição especial prevalece sobre a comum."]'::jsonb, '["Exceção do inciso I incluída pela Lei nº 15.358, de 2026.","Ordem: júri; mesma categoria (pena, número, prevenção); maior graduação; especial."]'::jsonb, 'Crime comum conexo a homicídio doloso: prevalece o Tribunal do Júri, em regra.', '["Assertiva que faz prevalecer a jurisdição comum sobre a especial na conexão erra."]'::jsonb, '[]'::jsonb, '["Art. 76","Art. 77","Art. 83"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-78'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A conexão e a continência importam unidade de processo e julgamento, salvo no concurso entre a jurisdição comum e a militar, e no concurso entre a jurisdição comum e a do juízo de menores. Cessa, em qualquer caso, a unidade do processo se, em relação a algum corréu, sobrevier o caso do art. 152 (doença mental superveniente). A unidade do processo não importará a do julgamento se houver corréu foragido que não possa ser julgado à revelia, ou ocorrer a hipótese do art. 461.', '["Regra: unidade de processo e julgamento.","Exceções: jurisdição militar e juízo de menores.","§1º: cessa se sobrevier doença mental a algum corréu.","§2º: corréu foragido ou hipótese do art. 461 não impede o julgamento dos demais."]'::jsonb, '["Exceções clássicas: militar e menores (justiça da infância)."]'::jsonb, 'Corréu foragido não impede o julgamento dos outros acusados.', '["Assertiva que obriga a unidade de julgamento entre jurisdição comum e militar erra."]'::jsonb, '[]'::jsonb, '["Art. 76","Art. 152","Art. 461"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-79'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'É facultativa a separação dos processos quando as infrações tiverem sido praticadas em circunstâncias de tempo ou de lugar diferentes, ou quando, pelo excessivo número de acusados e para não lhes prolongar a prisão provisória, ou por outro motivo relevante, o juiz reputar conveniente a separação.', '["Separação facultativa dos processos.","Hipóteses: tempo ou lugar diferentes; número excessivo de acusados; outro motivo relevante."]'::jsonb, '["A separação é discricionária do juiz."]'::jsonb, 'Juiz separa o processo de acusados presos para não alongar a prisão provisória.', '["Assertiva que torna obrigatória a separação em razão do número de acusados erra: é facultativa."]'::jsonb, '[]'::jsonb, '["Art. 79"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-80'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Verificada a reunião dos processos por conexão ou continência, ainda que no processo da sua competência própria o juiz ou tribunal venha a proferir sentença absolutória ou a desclassificar a infração para outra que não se inclua na sua competência, continuará competente em relação aos demais processos (perpetuação da jurisdição). Reconhecida inicialmente ao júri a competência por conexão ou continência, o juiz que desclassificar a infração, impronunciar ou absolver o acusado de modo a excluir a competência do júri remeterá o processo ao juízo competente.', '["Reunidos os processos, o juízo continua competente mesmo com absolvição ou desclassificação.","Parágrafo único: exclusão da competência do júri leva à remessa ao juízo competente."]'::jsonb, '["Perpetuação da jurisdição na conexão e continência, com exceção do Júri."]'::jsonb, 'O juiz absolve do crime de sua competência própria, mas continua julgando os conexos.', '["Assertiva que determina o declínio da competência após a absolvição pelo crime de competência própria erra."]'::jsonb, '[]'::jsonb, '["Art. 78"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-81'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Se, não obstante a conexão ou continência, forem instaurados processos diferentes, a autoridade de jurisdição prevalente deve avocar os processos que corram perante os outros juízes, salvo se já estiverem com sentença definitiva. Neste caso, a unidade dos processos só se dará, ulteriormente, para efeito de soma ou unificação das penas.', '["Processos separados apesar da conexão: o juízo prevalente avoca os demais.","Exceção: processo já com sentença definitiva.","Nesse caso, a unidade só serve à soma ou unificação das penas."]'::jsonb, '["Súmula 235 do STJ: a conexão não determina a reunião de processos se um deles já foi julgado."]'::jsonb, 'Dois processos conexos tramitam separados: o do juízo prevalente avoca o outro, se ainda não sentenciado.', '["Assertiva que determina a avocação de processo já com sentença definitiva erra."]'::jsonb, '[]'::jsonb, '["Art. 78"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-82'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Verifica-se a competência por prevenção toda vez que, concorrendo dois ou mais juízes igualmente competentes ou com jurisdição cumulativa, um deles tiver antecedido aos outros na prática de algum ato do processo ou de medida a este relativa, ainda que anterior ao oferecimento da denúncia ou da queixa.', '["Prevenção: o juiz que primeiro pratica ato do processo ou medida a ele relativa.","Vale mesmo para ato anterior à denúncia ou queixa."]'::jsonb, '["Remissões do artigo: arts. 70, §3º, 71, 72, §2º, e 78, II, c."]'::jsonb, 'O juiz que decretou a quebra de sigilo na investigação previne a competência para a ação.', '["Assertiva que restringe a prevenção a atos posteriores à denúncia erra."]'::jsonb, '[{"termo":"Prevenção","significado":"Fixação da competência pelo juiz que primeiro conheceu do caso."}]'::jsonb, '["Art. 75"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-83'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A competência pela prerrogativa de função é do Supremo Tribunal Federal, do Superior Tribunal de Justiça, dos Tribunais Regionais Federais e dos Tribunais de Justiça dos Estados e do Distrito Federal, relativamente às pessoas que devam responder perante eles por crimes comuns e de responsabilidade. Os parágrafos foram objeto de ação direta de inconstitucionalidade.', '["Prerrogativa de função: STF, STJ, TRFs e TJs.","Aplica-se a quem responde perante esses tribunais por crimes comuns e de responsabilidade."]'::jsonb, '["Os §§1º e 2º foram declarados inconstitucionais no STF (ADIN)."]'::jsonb, 'Governador de Estado é julgado, nos crimes comuns, pelo Superior Tribunal de Justiça.', '["Assertiva que afasta o STF do rol de tribunais com competência por prerrogativa de função erra."]'::jsonb, '[{"termo":"Foro por prerrogativa de função","significado":"Competência de tribunal em razão do cargo do acusado."}]'::jsonb, '["Art. 86","Art. 87"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-84'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Nos processos por crime contra a honra em que forem querelantes as pessoas sujeitas à jurisdição do Supremo Tribunal Federal e dos Tribunais de Apelação, a eles caberá o julgamento quando oposta e admitida a exceção da verdade.', '["Crime contra a honra com querelante de foro especial.","Exceção da verdade oposta e admitida desloca o julgamento ao tribunal competente."]'::jsonb, '["Relaciona-se com a exceção da verdade (arts. 138, §3º e 139 do Código Penal)."]'::jsonb, 'Querelado em calúnia contra autoridade com foro opõe exceção da verdade, e o tribunal a julga.', '["Assertiva que desloca a competência sem a admissão da exceção da verdade erra."]'::jsonb, '[{"termo":"Exceção da verdade","significado":"Defesa em que o querelado tenta provar a veracidade da imputação."}]'::jsonb, '["Art. 84"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-85'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Ao Supremo Tribunal Federal compete privativamente processar e julgar seus ministros nos crimes comuns; os ministros de Estado, salvo nos crimes conexos com os do Presidente da República; e o procurador-geral da República, os desembargadores dos Tribunais de Apelação, os ministros do Tribunal de Contas e os embaixadores e ministros diplomáticos, nos crimes comuns e de responsabilidade.', '["Ministros do STF nos crimes comuns.","Ministros de Estado, salvo crimes conexos com os do Presidente.","Procurador-geral da República, desembargadores, ministros do Tribunal de Contas e diplomatas, nos crimes comuns e de responsabilidade."]'::jsonb, '["Texto anterior à Constituição atual: a competência vigente é a prevista na Constituição."]'::jsonb, 'A competência atual do STF segue o art. 102 da Constituição.', '["Assertiva que aplica literalmente o art. 86 sem observar a Constituição atual erra."]'::jsonb, '[]'::jsonb, '["Art. 84"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-86'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Compete, originariamente, aos Tribunais de Apelação o julgamento dos governadores ou interventores nos Estados ou Territórios, do prefeito do Distrito Federal, seus respectivos secretários e chefes de Polícia, juízes de instância inferior e órgãos do Ministério Público.', '["Tribunais de Apelação julgam originariamente governadores, secretários, chefes de Polícia, juízes de instância inferior e membros do Ministério Público."]'::jsonb, '["Dispositivo histórico: a competência atual é fixada pela Constituição e pelas constituições estaduais."]'::jsonb, 'Hoje, um juiz estadual é julgado nos crimes comuns pelo Tribunal de Justiça.', '["Assertiva que aplica o art. 87 sem considerar a Constituição atual erra."]'::jsonb, '[]'::jsonb, '["Art. 84"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-87'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'No processo por crimes praticados fora do território brasileiro, será competente o juízo da Capital do Estado onde houver por último residido o acusado. Se este nunca tiver residido no Brasil, será competente o juízo da Capital da República.', '["Crime no exterior: Capital do Estado da última residência do acusado.","Se nunca residiu no Brasil: juízo da Capital da República."]'::jsonb, '["Aplicável quando a lei brasileira alcança crime cometido no exterior (extraterritorialidade)."]'::jsonb, 'Brasileiro que cometeu crime no exterior, com última residência em Rio Branco, é julgado na Capital do Estado.', '["Assertiva que fixa o foro no local do crime no exterior erra: é a Capital do Estado da última residência."]'::jsonb, '[]'::jsonb, '["Art. 7º do Código Penal"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-88'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Os crimes cometidos em qualquer embarcação nas águas territoriais da República, ou nos rios e lagos fronteiriços, bem como a bordo de embarcações nacionais em alto-mar, são processados e julgados pela justiça do primeiro porto brasileiro em que tocar a embarcação após o crime ou, quando se afastar do País, pela do último em que houver tocado.', '["Crimes em embarcações: justiça do primeiro porto brasileiro em que tocar após o crime.","Se se afastar do País: justiça do último porto em que tocou."]'::jsonb, '["Na Justiça Federal, a competência é regulada pela Constituição (crimes a bordo de navios)."]'::jsonb, 'Crime a bordo de navio nacional em alto-mar: julga-se no primeiro porto brasileiro tocado.', '["Assertiva que fixa o foro no porto de partida da embarcação erra."]'::jsonb, '[]'::jsonb, '["Art. 90","Art. 91"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-89'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Os crimes praticados a bordo de aeronave nacional, dentro do espaço aéreo correspondente ao território brasileiro ou ao alto-mar, ou a bordo de aeronave estrangeira dentro do espaço aéreo correspondente ao território nacional, são processados e julgados pela justiça da comarca em cujo território se verificar o pouso após o crime, ou pela da comarca de onde houver partido a aeronave.', '["Crime em aeronave: comarca do pouso após o crime ou da partida da aeronave."]'::jsonb, '["Observa a Constituição quanto à competência federal."]'::jsonb, 'Crime durante voo: pode ser julgado na comarca do pouso.', '["Assertiva que fixa só a comarca da partida erra: o pouso também é critério."]'::jsonb, '[]'::jsonb, '["Art. 89","Art. 91"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-90'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Quando incerta e não se determinar de acordo com as normas estabelecidas nos arts. 89 e 90, a competência se firmará pela prevenção.', '["Competência incerta nos casos de embarcação e aeronave: prevenção."]'::jsonb, '["Critério subsidiário."]'::jsonb, 'Quando não se determinar o foro pelos arts. 89 e 90, decide a prevenção.', '["Assertiva que aplica a prevenção antes dos critérios dos arts. 89 e 90 erra."]'::jsonb, '[]'::jsonb, '["Art. 89","Art. 90"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-91'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Se a decisão sobre a existência da infração depender da solução de controvérsia, que o juiz repute séria e fundada, sobre o estado civil das pessoas, o curso da ação penal ficará suspenso até que no juízo cível a controvérsia seja dirimida por sentença transitada em julgado, sem prejuízo da inquirição das testemunhas e de outras provas urgentes. Se for crime de ação pública, o Ministério Público, quando necessário, promoverá a ação civil ou prosseguirá na que tiver sido iniciada, com a citação dos interessados.', '["Questão prejudicial obrigatória: estado civil das pessoas.","Suspensão da ação penal até a sentença cível transitar em julgado.","Provas urgentes e oitiva de testemunhas continuam.","MP promove a ação civil, se necessário."]'::jsonb, '["Prejudicial OBRIGATÓRIA: controvérsia séria e fundada sobre o estado civil."]'::jsonb, 'Bigamia: validade do primeiro casamento é questão cível prejudicial.', '["Assertiva que torna facultativa a suspensão por questão de estado civil erra: é obrigatória, se séria e fundada."]'::jsonb, '[{"termo":"Questão prejudicial","significado":"Questão de outro ramo que deve ser resolvida antes do mérito penal."}]'::jsonb, '["Art. 93","Art. 94"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-92'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Se o reconhecimento da existência da infração penal depender de decisão sobre questão diversa da do artigo anterior, da competência do juízo cível, e se neste houver sido proposta ação para resolvê-la, o juiz criminal pode, desde que a questão seja de difícil solução e não verse sobre direito cuja prova a lei civil limite, suspender o curso do processo, após a inquirição das testemunhas e a realização das outras provas urgentes. O juiz marcará o prazo da suspensão, que poderá ser razoavelmente prorrogado se a demora não for imputável à parte; expirado o prazo sem decisão do juiz cível, o criminal prosseguirá e resolverá toda a matéria. Do despacho que denegar a suspensão não cabe recurso. Suspenso o processo, no crime de ação pública, o MP intervém na causa cível para promover-lhe o rápido andamento.', '["Prejudicial FACULTATIVA: questão cível de difícil solução, com ação cível já proposta.","Suspensão após provas urgentes.","§1º: prazo marcado, prorrogável; esgotado, o juiz criminal resolve tudo.","§2º: sem recurso contra a denegação.","§3º: MP intervém na causa cível."]'::jsonb, '["Na prejudicial facultativa, a suspensão é discricionária e exige ação cível já proposta."]'::jsonb, 'Discussão cível sobre a propriedade de um bem pode suspender o processo do crime de furto.', '["Assertiva que admite recurso contra o despacho que denega a suspensão erra: o §2º veda."]'::jsonb, '[]'::jsonb, '["Art. 92","Art. 94"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-93'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A suspensão do curso da ação penal, nos casos dos artigos anteriores, será decretada pelo juiz, de ofício ou a requerimento das partes.', '["Suspensão por questão prejudicial: decretada de ofício ou a requerimento."]'::jsonb, '["Vale para os arts. 92 e 93."]'::jsonb, 'Juiz decreta de ofício a suspensão do processo por questão prejudicial.', '["Assertiva que exige requerimento das partes para suspender o processo por prejudicial erra."]'::jsonb, '[]'::jsonb, '["Art. 92","Art. 93"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-94'
