insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Nas exceções de litispendência, ilegitimidade de parte e coisa julgada, observa-se, no que for aplicável, o disposto sobre a exceção de incompetência do juízo. Se a parte tiver de opor mais de uma dessas exceções, deve fazê-lo numa só petição ou articulado. A exceção de coisa julgada somente pode ser oposta em relação ao fato principal, que tiver sido objeto da sentença.', '["Litispendência, ilegitimidade de parte e coisa julgada seguem o rito da incompetência.","Várias exceções: numa só petição.","Coisa julgada: só em relação ao fato principal objeto da sentença."]'::jsonb, '["Coisa julgada refere-se ao FATO principal."]'::jsonb, 'O réu opõe numa só petição as exceções de litispendência e coisa julgada.', '["Assertiva que exige petições separadas para cada exceção erra."]'::jsonb, '[]'::jsonb, '["Art. 108"]'::jsonb, 'under_review', 'claude'
