select u.id, u.content_sha256, 'As exceções serão processadas em autos apartados e não suspenderão, em regra, o andamento da ação penal.', '["Exceções em autos apartados.","Em regra, não suspendem a ação penal."]'::jsonb, '["A regra é a não suspensão."]'::jsonb, 'A exceção de suspeição tramita em apartado, e o processo principal segue.', '["Assertiva que suspende sempre a ação penal durante o processamento de exceções erra."]'::jsonb, '[]'::jsonb, '["Art. 102"]'::jsonb, 'under_review', 'claude'
