select u.id, u.content_sha256, 'Realizado o sequestro, o juiz ordenará a sua inscrição no Registro de Imóveis.', '["Sequestro de imóvel: inscrição no Registro de Imóveis."]'::jsonb, '["Dá publicidade à constrição."]'::jsonb, 'Depois de sequestrar o imóvel, o juiz determina o registro da medida na matrícula.', '["Assertiva que dispensa a inscrição do sequestro no Registro de Imóveis erra."]'::jsonb, '[]'::jsonb, '["Art. 129"]'::jsonb, 'under_review', 'claude'
