insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O sequestro poderá ainda ser embargado pelo acusado, sob o fundamento de não terem os bens sido adquiridos com os proventos da infração, e pelo terceiro a quem houverem sido transferidos os bens a título oneroso, sob o fundamento de tê-los adquirido de boa-fé. Não poderá ser pronunciada decisão nesses embargos antes de passar em julgado a sentença condenatória.', '["Embargos do acusado: bens não adquiridos com proventos da infração.","Embargos do terceiro: aquisição onerosa de boa-fé.","Decisão só depois do trânsito em julgado da sentença condenatória."]'::jsonb, '["A decisão dos embargos fica DIFERIDA até o trânsito em julgado."]'::jsonb, 'Terceiro comprador de boa-fé embarga o sequestro, mas a decisão só vem após o trânsito.', '["Assertiva que permite decidir os embargos antes do trânsito da condenação erra."]'::jsonb, '[]'::jsonb, '["Art. 129"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-130'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O sequestro será levantado se a ação penal não for intentada no prazo de sessenta dias, contado da data em que ficar concluída a diligência; se o terceiro, a quem tiverem sido transferidos os bens, prestar caução que assegure a aplicação do disposto no art. 74, II, b, segunda parte, do Código Penal; ou se for julgada extinta a punibilidade ou absolvido o réu, por sentença transitada em julgado.', '["I: ação penal não intentada em sessenta dias da diligência.","II: terceiro presta caução.","III: extinção da punibilidade ou absolvição transitada em julgado."]'::jsonb, '["Prazo de sessenta dias para a ação penal."]'::jsonb, 'Passados sessenta dias sem ação penal, o sequestro é levantado.', '["Assertiva que mantém o sequestro após a absolvição transitada em julgado erra."]'::jsonb, '[]'::jsonb, '["Art. 125"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-131'
