on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Transitada em julgado a sentença condenatória, o juiz, de ofício ou a requerimento do interessado ou do Ministério Público, determinará a avaliação e a venda dos bens em leilão público cujo perdimento tenha sido decretado. Do dinheiro apurado, será recolhido aos cofres públicos o que não couber ao lesado ou a terceiro de boa-fé. O valor apurado deverá ser recolhido ao Fundo Penitenciário Nacional, exceto se houver previsão diversa em lei especial.', '["Após o trânsito da condenação: avaliação e leilão dos bens com perdimento decretado.","Pode ser de ofício ou a requerimento.","O que não couber ao lesado ou terceiro de boa-fé vai aos cofres públicos.","Valor ao Fundo Penitenciário Nacional, salvo lei especial."]'::jsonb, '["Destino: Fundo Penitenciário Nacional."]'::jsonb, 'Imóvel com perdimento decretado é leiloado e o valor vai ao Fundo Penitenciário Nacional.', '["Assertiva que destina o valor apurado ao Tesouro estadual erra: vai ao Fundo Penitenciário Nacional, salvo lei especial."]'::jsonb, '[]'::jsonb, '["Art. 122"]'::jsonb, 'under_review', 'claude'
