insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O juiz poderá autorizar, constatado o interesse público, a utilização de bem sequestrado, apreendido ou sujeito a qualquer medida assecuratória pelos órgãos de segurança pública do art. 144 da Constituição, do sistema prisional, do sistema socioeducativo, da Força Nacional de Segurança Pública e do Instituto Geral de Perícia, para o desempenho de suas atividades. O órgão participante das ações de investigação ou repressão da infração que ensejou a constrição do bem tem prioridade. Fora dessas hipóteses, demonstrado o interesse público, o juiz pode autorizar o uso pelos demais órgãos públicos. Se o bem for veículo, embarcação ou aeronave, o juiz ordenará à autoridade de trânsito ou ao órgão de registro a expedição de certificado provisório de registro e licenciamento em favor do órgão beneficiário, isento de multas, encargos e tributos anteriores à disponibilização do bem, que serão cobrados do responsável.', '["Uso de bem constrito por órgãos de segurança pública, sistema prisional e socioeducativo, Força Nacional e perícia.","Prioridade do órgão que participou da investigação.","Demais órgãos públicos: uso autorizado por interesse público.","Veículos, embarcações e aeronaves: certificado provisório e isenção de encargos anteriores."]'::jsonb, '["Exige interesse público e autorização judicial."]'::jsonb, 'Viatura apreendida é cedida à polícia que participou da investigação, com certificado provisório.', '["Assertiva que dispensa autorização judicial para a utilização do bem apreendido erra."]'::jsonb, '[]'::jsonb, '["Art. 133"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-133-a'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A hipoteca legal sobre os imóveis do indiciado poderá ser requerida pelo ofendido em qualquer fase do processo, desde que haja certeza da infração e indícios suficientes da autoria.', '["Hipoteca legal sobre imóveis do indiciado, requerida pelo ofendido.","Em qualquer fase do processo.","Exige certeza da infração e indícios suficientes da autoria."]'::jsonb, '["Exigência: certeza da infração e indícios suficientes de autoria (diferente do sequestro)."]'::jsonb, 'Ofendido requer a hipoteca legal sobre imóvel do acusado para garantir a reparação.', '["Assertiva que admite a hipoteca legal com simples suspeita da infração erra."]'::jsonb, '[{"termo":"Hipoteca legal","significado":"Garantia sobre imóveis do indiciado para assegurar a reparação do dano."}]'::jsonb, '["Art. 135"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-134'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Pedida a especialização mediante requerimento, em que a parte estimará o valor da responsabilidade civil e designará e estimará o imóvel ou imóveis que ficarão especialmente hipotecados, o juiz mandará proceder ao arbitramento do valor da responsabilidade e à avaliação dos imóveis. A petição é instruída com as provas da estimação, com a relação dos imóveis do responsável e com os documentos do domínio. O arbitramento e a avaliação são feitos por perito nomeado pelo juiz, onde não houver avaliador judicial. O juiz, ouvidas as partes em dois dias, pode corrigir o arbitramento. Autorizará somente a inscrição da hipoteca dos imóveis necessários à garantia. O valor da responsabilidade será liquidado definitivamente após a condenação, podendo ser requerido novo arbitramento.', '["Requerimento estima o valor da responsabilidade civil e indica os imóveis.","Arbitramento e avaliação por perito.","Partes ouvidas em dois dias; juiz pode corrigir o valor.","Hipoteca somente dos imóveis necessários.","Liquidação definitiva após a condenação."]'::jsonb, '["Hipoteca limitada aos imóveis necessários à garantia."]'::jsonb, 'Juiz autoriza a hipoteca de apenas um imóvel, suficiente para garantir o valor arbitrado.', '["Assertiva que autoriza a hipoteca de todos os imóveis do acusado independentemente do valor erra."]'::jsonb, '[]'::jsonb, '["Art. 134"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-135'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O arresto do imóvel poderá ser decretado de início, revogando-se, porém, se no prazo de 15 dias não for promovido o processo de inscrição da hipoteca legal.', '["Arresto do imóvel decretado desde logo.","Revogado se, em 15 dias, a hipoteca legal não for promovida."]'::jsonb, '["Prazo de 15 dias."]'::jsonb, 'Imóvel arrestado cautelarmente: a medida cai se a hipoteca não for requerida em 15 dias.', '["Assertiva que fixa em 60 dias o prazo para promover a hipoteca legal após o arresto erra: são 15 dias."]'::jsonb, '[{"termo":"Arresto","significado":"Medida cautelar prévia que garante o bem até a hipoteca legal."}]'::jsonb, '["Art. 134"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-136'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Se o responsável não possuir bens imóveis ou os possuir de valor insuficiente, poderão ser arrestados bens móveis suscetíveis de penhora, nos termos em que é facultada a hipoteca legal dos imóveis. Se forem coisas fungíveis e facilmente deterioráveis, procede-se na forma do § 5º do art. 120. Das rendas dos bens móveis poderão ser fornecidos recursos arbitrados pelo juiz para a manutenção do indiciado e de sua família.', '["Sem imóveis ou com valor insuficiente: arresto de bens móveis penhoráveis.","Coisas fungíveis e deterioráveis: procedimento do art. 120, §5º.","Rendas podem manter o indiciado e sua família, conforme arbitramento."]'::jsonb, '["O juiz pode arbitrar recursos para a subsistência do indiciado e da família."]'::jsonb, 'Réu sem imóveis tem bens móveis penhoráveis arrestados.', '["Assertiva que impede o fornecimento de recursos ao indiciado e à família das rendas dos bens arrestados erra."]'::jsonb, '[]'::jsonb, '["Art. 120","Art. 136"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-137'
