insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'As garantias do ressarcimento do dano alcançarão também as despesas processuais e as penas pecuniárias, tendo preferência sobre estas a reparação do dano ao ofendido.', '["As garantias abrangem despesas processuais e penas pecuniárias.","A reparação do dano ao ofendido tem preferência."]'::jsonb, '["Preferência: primeiro a vítima."]'::jsonb, 'Com patrimônio limitado, a reparação à vítima é satisfeita antes da multa.', '["Assertiva que dá preferência às penas pecuniárias sobre a reparação do dano erra."]'::jsonb, '[]'::jsonb, '["Art. 134"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-140'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();
